<section class="tracking-section container"><div><span class="eyebrow">ACOMPANHE SUA COMPRA</span><h1>Onde está meu pedido?</h1><p>Informe o código do pedido e o mesmo e-mail utilizado na compra.</p></div><form class="tracking-card" method="post" action="<?=e(url('/rastrear-pedido'))?>"><?=csrf_field()?><label>Código do pedido<input name="code" maxlength="50" required value="<?=e($input['code'])?>" placeholder="Ex.: TF-10001"></label><label>E-mail da compra<input type="email" name="email" maxlength="190" required value="<?=e($input['email'])?>" placeholder="voce@email.com"></label><button class="button button--primary">Rastrear pedido</button><?php if($trackingError):?><p class="tracking-error"><?=e($trackingError)?></p><?php endif;?></form></section>
<?php if($tracking):?><section class="tracking-results container"><header><div><span class="eyebrow">PEDIDO <?=e($tracking['order']['code'])?></span><h2>Acompanhamento da entrega</h2><p>Atualizado com os dados disponíveis das transportadoras.</p></div><?php $status=$tracking['order']['status'];require dirname(__DIR__,2).'/components/dashboard/status-badge.php';?></header><div class="tracking-result-grid"><?php foreach($tracking['shipments'] as $shipment):?><article class="tracking-result-card"><div class="tracking-result-head"><div><small><?=e($shipment['seller_order_code'])?></small><h3><?=e($shipment['store_name'])?></h3></div><?php $status=$shipment['status'];require dirname(__DIR__,2).'/components/dashboard/status-badge.php';?></div><p><?=e($shipment['service_name']?:'Entrega')?> · <?=e($shipment['carrier_name']?:'Transportadora')?></p><?php if($shipment['tracking_code']):?><strong>Código: <?=e($shipment['tracking_code'])?></strong><?php endif;?><?php if($shipment['tracking_url']):?><a class="button button--secondary" href="<?=e($shipment['tracking_url'])?>" target="_blank" rel="noopener noreferrer">Abrir rastreio da transportadora</a><?php endif;?><div class="tracking-timeline"><?php foreach($shipment['events'] as $event):?><div><i></i><p><strong><?=e($event['description'])?></strong><small><?=date('d/m/Y H:i',strtotime($event['occurred_at']))?><?=!empty($event['city'])?' · '.e($event['city'].'/'.$event['state']):''?></small></p></div><?php endforeach;?><?php if(!$shipment['events']):?><div><i></i><p><strong>Pedido em preparação</strong><small>O rastreamento aparecerá após a postagem.</small></p></div><?php endif;?></div></article><?php endforeach;?></div></section><?php endif;?>
